<?php
declare(strict_types=1);require dirname(__DIR__).'/bootstrap.php';use OtpAuth\CustomerService;use OtpAuth\Database;$customer=(new CustomerService(Database::connection()))->customerFromSession((string)($_COOKIE['otp_auth_session']??''));
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>OTP Auth — Customer Dashboard A</title><link rel="stylesheet" href="/assets/app.css"></head><body><main class="container"><header class="hero"><div><p class="eyebrow">OTP AUTH</p><h1>Customer Dashboard A</h1><p>Projects → verified domain → OTP-Auth subdomain → sender identities → API keys → integration.</p></div><?php if($customer):?><button id="logout">Log out</button><?php endif;?></header>
<?php if(!$customer):?><section class="grid"><article class="card"><h2>Create account</h2><form id="register"><input name="email" type="email" placeholder="Email" required><input name="password" type="password" minlength="10" placeholder="Password (10+ chars)" required><button>Create account</button></form></article><article class="card"><h2>Sign in</h2><form id="login"><input name="email" type="email" placeholder="Email" required><input name="password" type="password" placeholder="Password" required><button>Login</button></form></article></section>
<?php else:?><section class="card"><h2>Welcome</h2><p><?=htmlspecialchars($customer['email'],ENT_QUOTES,'UTF-8')?></p><p class="muted">Every project is isolated. Verify the real customer domain before reserving a platform subdomain.</p></section><section class="card"><h2>Create project</h2><form id="project"><input name="name" maxlength="120" placeholder="MyShop" required><button>Create project</button></form></section><section class="card"><h2>Projects</h2><div id="projects">Loading…</div></section><section class="card" id="workspace" hidden><h2 id="workspace-title">Project</h2><p id="workspace-meta"></p><div class="grid"><article class="card"><h3>Domain verification</h3><form id="domain"><input name="domain" placeholder="slotcare.com" required><button>Generate TXT</button></form><pre id="domain-result"></pre><button id="verify-domain" type="button" hidden>Verify DNS</button></article><article class="card"><h3>OTP-Auth subdomain</h3><form id="subdomain"><input name="subdomain" placeholder="slotcare" required><button>Reserve</button></form><pre id="subdomain-result"></pre></article><article class="card"><h3>Widget allowed origin</h3><form id="origins"><input name="origin" placeholder="https://slotcare.com" required><button>Save origin</button></form><pre id="origin-result"></pre></article><article class="card"><h3>Sender identities</h3><form id="sender"><input name="local_part" placeholder="verification" required><input name="display_name" placeholder="Verification"><button>Create sender</button></form><div id="senders"></div></article><article class="card"><h3>Developer API keys</h3><form id="key"><input name="name" placeholder="Production API" required><select name="environment"><option value="test">test</option><option value="production">production</option></select><button>Create secret key</button></form><pre id="key-result"></pre><div id="keys"></div></article><article class="card"><h3>Easy Integration</h3><p>The browser receives only the public project ID. Never expose a secret API key here.</p><pre id="snippet"></pre><button id="copy-snippet" type="button">Copy snippet</button></article></div></section><?php endif;?><pre id="status"></pre></main>
<script>
const out=x=>document.getElementById('status').textContent=typeof x==='string'?x:JSON.stringify(x,null,2);const csrf=()=>decodeURIComponent(document.cookie.split('; ').find(x=>x.startsWith('otp_auth_csrf='))?.split('=')[1]||'');async function post(path,data){const h={'Content-Type':'application/json'},c=csrf();if(c)h['X-CSRF-Token']=c;const r=await fetch(path,{method:'POST',headers:h,body:JSON.stringify(data)}),j=await r.json();if(!r.ok)throw j;return j}
<?php if(!$customer):?>
document.getElementById('register').onsubmit=async e=>{e.preventDefault();try{out(await post('/api/v1/customer/register',Object.fromEntries(new FormData(e.target))))}catch(x){out(x)}};document.getElementById('login').onsubmit=async e=>{e.preventDefault();try{await post('/api/v1/customer/login',Object.fromEntries(new FormData(e.target)));location.reload()}catch(x){out(x)}};
<?php else:?>
let current=null,domainReady=false;function esc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));}document.getElementById('logout').onclick=async()=>{try{await post('/api/v1/customer/logout',{});location.reload()}catch(x){out(x)}};document.getElementById('project').onsubmit=async e=>{e.preventDefault();try{await post('/api/v1/customer/project-create',Object.fromEntries(new FormData(e.target)));e.target.reset();load()}catch(x){out(x)}};
async function load(){try{const j=await post('/api/v1/customer/projects',{});document.getElementById('projects').innerHTML=(j.projects||[]).map(p=>'<div class="card"><strong>'+esc(p.name)+'</strong><br>Status: '+esc(p.status)+'<br>Domain: '+esc(p.website_domain||'Not added')+'<br>Subdomain: '+esc(p.otp_subdomain||'Not reserved')+'<br><button type="button" onclick="selectProject('+p.id+')">Manage</button></div>').join('')||'No projects yet.'}catch(x){out(x)}}window.selectProject=async id=>{current=id;document.getElementById('workspace').hidden=false;try{const p=(await post('/api/v1/customer/projects',{})).projects.find(x=>x.id===id);document.getElementById('workspace-title').textContent=p.name;document.getElementById('workspace-meta').textContent='Project '+p.id+' · '+p.status+' · Public ID '+p.public_id;document.getElementById('snippet').textContent='<script src="'+location.origin+'/widget.js"><\\/script>\n<div id="otp-auth"></div>\n<script>OtpAuth.init({ project: "'+p.public_id+'", purpose: "login" });<\\/script>';refresh()}catch(x){out(x)}};
async function refresh(){try{const w=await post('/api/v1/customer/widget-settings',{project_id:current});document.getElementById('origin-result').textContent=JSON.stringify(w.allowed_origins||[],null,2);const s=await post('/api/v1/customer/senders',{project_id:current});document.getElementById('senders').innerHTML=(s.senders||[]).map(x=>'<p>'+esc(x.full_address)+' — '+esc(x.status)+'</p>').join('')||'No sender identities.';const k=await post('/api/v1/customer/keys',{project_id:current});document.getElementById('keys').innerHTML=(k.keys||[]).map(x=>'<p>'+esc(x.name)+' — '+esc(x.environment)+' — '+esc(x.key_prefix)+'… — '+esc(x.status)+'</p>').join('')||'No secret API keys.'}catch(x){out(x)}}document.getElementById('domain').onsubmit=async e=>{e.preventDefault();try{const r=await post('/api/v1/customer/domain-start',{project_id:current,...Object.fromEntries(new FormData(e.target))});document.getElementById('domain-result').textContent=JSON.stringify(r.verification,null,2);domainReady=true;document.getElementById('verify-domain').hidden=false}catch(x){out(x)}};document.getElementById('verify-domain').onclick=async()=>{try{const r=await post('/api/v1/customer/domain-verify',{project_id:current});document.getElementById('domain-result').textContent=JSON.stringify(r,null,2);load()}catch(x){out(x)}};document.getElementById('subdomain').onsubmit=async e=>{e.preventDefault();try{const r=await post('/api/v1/customer/subdomain',{project_id:current,...Object.fromEntries(new FormData(e.target))});document.getElementById('subdomain-result').textContent=JSON.stringify(r,null,2);load();refresh()}catch(x){out(x)}};document.getElementById('origins').onsubmit=async e=>{e.preventDefault();try{const r=await post('/api/v1/customer/widget-origins',{project_id:current,origins:[e.target.origin.value]});document.getElementById('origin-result').textContent=JSON.stringify(r.allowed_origins,null,2)}catch(x){out(x)}};document.getElementById('sender').onsubmit=async e=>{e.preventDefault();try{await post('/api/v1/customer/sender-create',{project_id:current,...Object.fromEntries(new FormData(e.target))});e.target.reset();refresh()}catch(x){out(x)}};document.getElementById('key').onsubmit=async e=>{e.preventDefault();try{const r=await post('/api/v1/customer/key-create',{project_id:current,...Object.fromEntries(new FormData(e.target))});document.getElementById('key-result').textContent='SAVE THIS SECRET NOW:\n'+r.key.key+'\n\nIt will not be shown again.';e.target.reset();refresh()}catch(x){out(x)}};document.getElementById('copy-snippet').onclick=()=>navigator.clipboard?.writeText(document.getElementById('snippet').textContent);load();
<?php endif;?>
</script></body></html>
